    public static int pmPushRoman(emon.Port.Cells out, int n, int upper) {
        // n as a Roman numeral pushed onto `out` as code points, M repeated past 3999 (as
        // poppler and qpdf do); nothing for n below 1.
        int m = n;
        int k = 0;
        int lower = 32;
        if (n < 1) {
            return 0;
        }
        if (upper == 1) {
            lower = 0;
        }
        while (k < 13) {
            while (m >= PM_RN[k * 3 + 0]) {
                emon.Port.cellsPush(out, PM_RN[k * 3 + 1] + lower);
                if (PM_RN[k * 3 + 2] != 0) {
                    emon.Port.cellsPush(out, PM_RN[k * 3 + 2] + lower);
                }
                m -= PM_RN[k * 3 + 0];
            }
            k += 1;
        }
        return 0;
    }
    public static int pmPushLetters(emon.Port.Cells out, int n, int upper) {
        // n as letters: A to Z, then AA to ZZ, then AAA (ISO 32000-1 12.4.2); nothing below 1.
        if (n < 1) {
            return 0;
        }
        int reps = ((n - 1) / 26) + 1;
        int c = ((n - 1) % 26) + 97;
        int i = 0;
        if (upper == 1) {
            c -= 32;
        }
        while (i < reps) {
            emon.Port.cellsPush(out, c);
            i += 1;
        }
        return 0;
    }
    public static int pmPushInt(emon.Port.Cells out, int v) {
        // v in decimal pushed onto `out` as code points.
        int m = v;
        int d = 1;
        if (v < 0) {
            emon.Port.cellsPush(out, 45);
            m = 0 - v;
        }
        while (d <= (m / 10)) {
            d *= 10;
        }
        while (d > 0) {
            emon.Port.cellsPush(out, 48 + ((m / d) % 10));
            d = d / 10;
        }
        return 0;
    }
    public static int pmLabelRange(emon.Port.Cells lb, int page) {
        // The row of the range page `page` falls in: the last whose first page is at or
        // before it and that is not a duplicate key; -1 when none does.
        int n = emon.Port.cellsLen(lb) / LB_STRIDE;
        int i = 0;
        int best = -1;
        while (i < n) {
            if (emon.Port.cellsAt(lb, i * LB_STRIDE) <= page) {
                if (((emon.Port.cellsAt(lb, (i * LB_STRIDE) + 6) / 4) % 2) == 0) {
                    best = i;
                }
            }
            i += 1;
        }
        return best;
    }
