        int before = emon.Port.cellsLen(out);
        if (r < 0) {
            return -1;
        }
        int at = r * LB_STRIDE;
        int style = emon.Port.cellsAt(lb, at + 1);
        int num = emon.Port.cellsAt(lb, at + 4) + (page - emon.Port.cellsAt(lb, at));
        int i = 0;
        int c = 0;
        while (i < emon.Port.cellsAt(lb, at + 3)) {
            c = emon.Port.cellsAt(txt, emon.Port.cellsAt(lb, at + 2) + i);
            emon.Port.cellsPush(out, c);
            i += 1;
        }
        if (style == 1) {
            pmPushInt(out, num);
        }
        if (style == 2) {
            pmPushRoman(out, num, 1);
        }
        if (style == 3) {
            pmPushRoman(out, num, 0);
        }
        if (style == 4) {
            pmPushLetters(out, num, 1);
        }
        if (style == 5) {
            pmPushLetters(out, num, 0);
        }
        return emon.Port.cellsLen(out) - before;
