    public static int pmRgb(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int arr) {
        // A /C colour array of three numbers in 0..1 as 0xRRGGBB, -1 when it is not one.
        if (arr == 0) {
            return -1;
        }
        if (Pdflex.plKindOf(ar, arr) != 6) {
            return -1;
        }
        if (Pdflex.plCount(ar, arr) != 3) {
            return -1;
        }
        int rgb = 0;
        int k = 0;
        int v = 0;
        int e = 0;
        int c = 0;
        while (k < 3) {
            e = Pdfx.pxNth(ar, arr, k);
            v = Pdfdoc.pdResolve(src, ar, dc, a, b, st, e);
            if (Pdfx.pxIsNum(ar, v) == 0) {
                return -1;
            }
            c = ((Pdflex.plNumCp(ar, v) * 255) + 50) / 100;
            if (c < 0) {
                c = 0;
            }
            if (c > 255) {
                c = 255;
            }
            rgb = (rgb * 256) + c;
            k += 1;
        }
        return rgb;
    }
